layout(binding = 5) readonly buffer QBank { uint w[]; } qb[NBANK];
// The same buffer again, as sixteen-byte words. A Q4_K super-block is 144
// bytes and a Q5_K one 176, both multiples of sixteen, so the 32 bytes of
// nibbles a lane unpacks per K-step are two aligned `uvec4` loads where they
// would otherwise be eight `uint` ones — and this kernel turned out to be
// bound by how many load instructions its unpack issues, not by the bytes
// they fetch. Q5_1's 24-byte and Q8_0's 34-byte blocks are not aligned to
// sixteen and go on reading the `uint` view.
layout(binding = 6) readonly buffer QBank4 { uvec4 w[]; } qb4[NBANK];
// The kernel goes on spelling them `qbank` and `qbank4`: which buffer of the
// array is the same fact for every load a dispatch issues, so it belongs at
// the declaration rather than at the 30-odd call sites.
#define qbank  qb[MOE_BANK].w
#define qbank4 qb4[MOE_BANK].w
// The **halves** arena again, as sixteen-byte words, for the grouped GEMM's
// gathered A operand (P11).
//
// `llm_moe_gemm.comp`'s MODE 0 stages BM scattered rows of the block input
// into LDS per K-step, and it was doing it one half at a time: BM*BK/LANES =
// 32 loads a lane a K-step at BM 64, each fetching **two bytes**, against the
// eight the B unpack issues for four times the data. The same reasoning that
// put the bank at binding 6 applies to the operand — this kernel is bound by
// how many load instructions it issues, not by the bytes they fetch — and a
// K-step of 32 halves is four aligned `uvec4` loads a row instead of 32
// scalar ones. The rows a gather names are the permutation's, so alignment is
// the *row stride's* to keep: `lda` and `xnOff` are both multiples of eight
// halves, which `MoEGPU.Upload` asserts rather than assumes.
layout(binding = 7) readonly buffer HAct4 { uvec4 hact4[]; };
#endif

// The **dense** weight bank read as raw words: LLM.md L8.
//
shared float kIQ4[16];
#endif

uint qbyte(uint b) { return (qbank[b >> 2] >> ((b & 3u) * 8u)) & 0xFFu; }

// **A K-quant block's header and its scales are one sixteen-byte load** (P12).
//
// Q4_K and Q5_K open every block with `d`, `dmin` and the twelve packed
// 6-bit scale/min bytes — sixteen bytes, read as four separate dwords. That
// is four load instructions a block a row where one `uvec4` does, and this
// kernel is bound by how many loads its unpack issues (L5b-7, P11-3): at BK
// 32 a lane unpacks two rows a K-step, so it was eight scalar loads a K-step
// against the four vector ones the nibbles take.
//
// It is legal because **every block of these two formats is sixteen-byte
// aligned**, and that is three facts rather than an assumption: each of the
// six bank regions starts at `roundUpInt(nbytes, 16)` (`MoEGPU.reserve`); a
// Q4_K row is `k/256 * 144` bytes and a Q5_K row `k/256 * 176`, both
// multiples of 16 (`moeRowBytes`); and the blocks inside a row are 144 and
// 176 apart. `MoEGPU.build` checks the first of those rather than trusting
// it, for the same reason P11 checked the gather's.

// The block header, in one load. `d` and its companion are the first four
// bytes of every one of these formats and the block base is four-aligned, so
// a pair of halves comes out of a single word rather than four byte reads.
vec2 qhdr(uint blk) { return unpackHalf2x16(qbank[blk >> 2]); }

#if QFMT == FMT_Q4_K || QFMT == FMT_Q5_K
// ggml's get_scale_min_k4: eight 6-bit scale/min pairs in twelve bytes, which
// is three words read once for the whole slab. The first four pairs are plain
// fields; the last four take their low nibble from bytes 8..11 and their top
// two bits from the spare bits of bytes 0..7.
uint sbyte(uvec3 s, uint i) {
    uint w = (i < 4u) ? s.x : ((i < 8u) ? s.y : s.z);
    return (w >> ((i & 3u) * 8u)) & 0xFFu;
}

void scaleMinK4(uint j, uvec3 s, out uint sc, out uint mn) {
    if (j < 4u) {
        sc = sbyte(s, j) & 63u;
        mn = sbyte(s, j + 4u) & 63u;
    } else {
        uint a = sbyte(s, j + 4u);
        sc = (a & 0xFu) | ((sbyte(s, j - 4u) >> 6) << 4);
        mn = (a >> 4) | ((sbyte(s, j) >> 6) << 4);
    }
}
#endif

