			for _, u := range llm.MoEDecodeKernels() {
				p = append(p, moePlan{du, dd, u, sd, ""})
			}
			for _, d := range llm.MoEDecodeKernels() {
				p = append(p, moePlan{du, dd, su, d, ""})
			}
