// TailRow copies out, for every staged layer, the pooled row of the block
// that holds cell `past`, which is not whole yet and so still holds what a
// fresh sequence filled it with: cell 0 pooled `ratio` times (blockRange).
// ResetTail writes that row back over blocks [from/ratio, to/ratio] (C4).
//
// **The tail score reads it.** llm_attn_score_wmma.comp scores block `nBid`,
// the first that is not whole, from its pooled row, and every block past it
// shares that one score. A continuation that ran from `from` to `to` and
// was then abandoned completed the blocks in between with its own keys, and
// nothing rewrites one until a later run completes it again, so a restored
// sequence would score its partial block from a stranger's keys. The
// selection survives that, but not bit for bit: the score is one term of
// the sort that orders the blocks a query reads.
func (g *AttnGPU) TailRow(past int) []uint16 {
	b := past / g.cfg.Ratio
	out := make([]uint16, 0, len(g.layers)*g.cfg.IdxDim)
	for l := range g.layers {
		out = append(out, g.ibuf.ReadUint16At(int(g.hIdxK)+l*g.idxKStride+b*g.cfg.IdxDim, g.cfg.IdxDim)...)
	}
	return out
}

// ResetTail is TailRow's other half; see there.
func (g *AttnGPU) ResetTail(from, to int, row []uint16) error {
	if len(row) != len(g.layers)*g.cfg.IdxDim {
		return fmt.Errorf("llm: a %d-value tail row against %d layers of %d", len(row), len(g.layers), g.cfg.IdxDim)
	}
	lo, hi := from/g.cfg.Ratio, min(to/g.cfg.Ratio, g.NBlocks()-1)
	if hi < lo {
		return nil
	}
	span := make([]uint16, (hi-lo+1)*g.cfg.IdxDim)
	for l := range g.layers {
		r := row[l*g.cfg.IdxDim : (l+1)*g.cfg.IdxDim]
		for b := 0; b <= hi-lo; b++ {
			copy(span[b*g.cfg.IdxDim:], r)
		}
		g.ibuf.WriteUint16At(int(g.hIdxK)+l*g.idxKStride+lo*g.cfg.IdxDim, span)
	}
	return nil
}

